 private static final int TEXT=android.text.InputType.TYPE_CLASS_TEXT,NUMBER=android.text.InputType.TYPE_CLASS_NUMBER;
 private static final ZoneId CHINA=ZoneId.of("Asia/Shanghai");
 private static String s(JSONObject o,String k){return MainActivity.s(o,k);}
 private static Spinner spinner(MainActivity a,LinearLayout parent,String key,String label,String[] labels,String[] values,String initial){NativeUi ui=a.ui();ui.gap(parent,16);parent.addView(ui.text(label,13,ui.muted,true));Spinner view=new Spinner(a);ArrayAdapter<String> adapter=new ArrayAdapter<String>(a,android.R.layout.simple_spinner_dropdown_item,labels){@Override public View getView(int position,View v,ViewGroup p){TextView text=ui.body(labels[position]);text.setPadding(ui.dp(16),ui.dp(14),ui.dp(16),ui.dp(14));return text;}@Override public View getDropDownView(int position,View v,ViewGroup p){TextView text=ui.body(labels[position]);text.setPadding(ui.dp(20),ui.dp(14),ui.dp(20),ui.dp(14));text.setBackgroundColor(ui.card);return text;}};view.setAdapter(adapter);view.setTag(values);view.setBackground(ui.shape(ui.tonal,16));view.setSelection(Math.max(0,Arrays.asList(values).indexOf(initial)));parent.addView(view,new LinearLayout.LayoutParams(-1,ui.dp(56)));a.choices().put(key,view);return view;}
 private static String choice(MainActivity a,String key){Spinner v=a.choices().get(key);return v==null?"":((String[])v.getTag())[v.getSelectedItemPosition()];}
 private static void date(MainActivity a,EditText field,boolean monday,Runnable update){field.setFocusable(false);field.setOnClickListener(v->{LocalDate d;try{d=LocalDate.parse(field.getText());}catch(Exception e){d=LocalDate.now(CHINA);}DatePickerDialog dialog=new DatePickerDialog(a,(picker,y,m,day)->{LocalDate chosen=LocalDate.of(y,m+1,day);if(monday)chosen=chosen.minusDays(chosen.getDayOfWeek().getValue()-1);field.setText(chosen.toString());if(update!=null)update.run();},d.getYear(),d.getMonthValue()-1,d.getDayOfMonth());dialog.show();});}
 static void render(MainActivity a){NativeUi ui=a.ui();LinearLayout parent=a.body();boolean self="self".equals(a.screen()),edit="edit".equals(a.screen());JSONObject b=a.draft().length()>0?a.draft():edit?a.selected():new JSONObject();if(b==null)b=new JSONObject();final JSONObject base=b;try{if(!a.draft().has("requestId"))a.draft().put("requestId",UUID.randomUUID().toString());}catch(Exception ignored){}
  ui.title(parent,self?"记录一餐":"edit".equals(a.screen())?"编辑用餐安排":"安排下一餐",self?"记录真实摄入，让坚持更有分寸。":"选择用餐日期所在周，预约一份期待。");
  LinearLayout c=ui.card(parent);c.addView(ui.text("用餐安排",21,ui.text,true));a.addField(c,"name","用餐人姓名",s(b,"name").isEmpty()?(self?"王亦达":s(a.user(),"nickname")):s(b,"name"),TEXT);
  a.addField(c,"partySize","人数 · 包含用餐人",s(b,"partySize").isEmpty()?String.valueOf(b.optInt("party_size",1)):s(b,"partySize"),NUMBER);
  spinner(a,c,"mealType","餐次",edit?new String[]{"午餐","晚餐","夜宵","未注明"}:new String[]{"午餐","晚餐","夜宵"},edit?new String[]{"lunch","dinner","late","unspecified"}:new String[]{"lunch","dinner","late"},s(b,"mealType").isEmpty()?(s(b,"meal_type").isEmpty()?"dinner":s(b,"meal_type")):s(b,"mealType"));
  LocalDateTime time=self?LocalDateTime.now(CHINA):LocalDate.now(CHINA).plusDays(1).atTime(18,30);try{if(!s(b,"mealAt").isEmpty())time=LocalDateTime.parse(s(b,"mealAt"));else if(!s(b,"meal_at").isEmpty())time=Instant.parse(s(b,"meal_at")).atZone(CHINA).toLocalDateTime();}catch(Exception ignored){}
  EditText day=a.addField(c,"date","用餐日期 · 北京时间",time.toLocalDate().toString(),TEXT),clock=a.addField(c,"time","用餐时间",time.toLocalTime().format(DateTimeFormatter.ofPattern("HH:mm")),TEXT);
  TextView quota=ui.text("",14,ui.muted,false);ui.gap(c,14);c.addView(quota);
  Runnable showQuota=()->{try{LocalDate monday=LocalDate.parse(a.val("date"));monday=monday.minusDays(monday.getDayOfWeek().getValue()-1);String week=monday.toString();int limit=2,count=0;JSONArray limits=MainActivity.arr(a.data(),"weeklyLimits");for(int i=0;i<limits.length();i++){JSONObject l=limits.optJSONObject(i);if("default".equals(s(l,"week")))limit=l.optInt("meal_limit",2);}for(int i=0;i<limits.length();i++){JSONObject l=limits.optJSONObject(i);if(week.equals(s(l,"week")))limit=l.optInt("meal_limit",2);}JSONArray qs=MainActivity.arr(a.data(),"quotas");for(int i=0;i<qs.length();i++){JSONObject q=qs.optJSONObject(i);if(week.equals(s(q,"week")))count=q.optInt("count");}quota.setText(monday+" — "+monday.plusDays(6)+"\n额度 "+limit+" 次 · 已用／占用 "+count+" 次 · 剩余 "+(limit-count)+" 次"+(limit-count<=0?(self?"\n自主记录仍可提交，超额后显示红色负额度。":"\n该周名额已满，请选择其他周。"):""));quota.setTextColor(limit-count<=0?ui.error:ui.muted);}catch(Exception ignored){}};
  date(a,day,false,showQuota);clock.setFocusable(false);clock.setOnClickListener(v->{String[] parts=clock.getText().toString().split(":");new TimePickerDialog(a,(picker,h,m)->clock.setText(String.format(Locale.ROOT,"%02d:%02d",h,m)),Integer.parseInt(parts[0]),Integer.parseInt(parts[1]),true).show();});showQuota.run();
  LinearLayout place=ui.card(parent);place.addView(ui.text("餐厅位置",21,ui.text,true));EditText name=a.addField(place,"restaurant","餐厅名称",s(b,"restaurant"),TEXT);EditText address=a.addField(place,"address","详细地址 · 选填",s(b,"address"),TEXT);
  if(!edit){ui.fullButton(place,"搜索餐厅 · 定位附近",false,()->a.pickPlace());TextWatcher changed=new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int af){}public void onTextChanged(CharSequence s,int st,int before,int count){a.draft().remove("latitude");a.draft().remove("longitude");}public void afterTextChanged(Editable e){}};name.addTextChangedListener(changed);address.addTextChangedListener(changed);}
  LinearLayout others=ui.card(parent);others.addView(ui.text("同行与补充信息",21,ui.text,true));LinearLayout rows=ui.column();others.addView(rows);String names=s(b,"companions");String[] existing=names.isEmpty()?new String[]{""}:names.split("、");final int[] previous={names.isEmpty()?0:existing.length};
  Runnable recompute=()->{int n=0;for(EditText e:a.companions())if(!e.getText().toString().trim().isEmpty())n++;if(n!=previous[0]){a.fields().get("partySize").setText(String.valueOf(n+1));previous[0]=n;}};
  for(String n:existing)addCompanion(a,rows,n,recompute);
  ui.fullButton(others,"＋ 添加同行人",false,()->{if(a.companions().size()<29)addCompanion(a,rows,"",recompute);else a.notifyError("最多29位同行人。");});others.addView(ui.text("填写姓名后自动更新人数；空白行不计入。",13,ui.muted,false));spinner(a,others,"transportMode","交通方式 · 选填",BookingLabels.TRANSPORT_LABELS,BookingLabels.TRANSPORT_VALUES,s(b,"transportMode").isEmpty()?s(b,"transport_mode"):s(b,"transportMode"));
  String amount=b.has("estimatedCost")?s(b,"estimatedCost"):b.isNull("estimated_cost_cents")?"":BookingLabels.amount(b.optLong("estimated_cost_cents"));a.addField(others,"estimatedCost","预估人均消费 · 元/人，选填",amount,NUMBER|android.text.InputType.TYPE_NUMBER_FLAG_DECIMAL);
  a.addField(others,"contact","联系方式 · 选填",s(b,"contact"),TEXT);EditText notes=a.addField(others,"notes","备注 · 选填",s(b,"notes"),TEXT|android.text.InputType.TYPE_TEXT_FLAG_MULTI_LINE);notes.setMinLines(3);
  if(self||edit&&"completed".equals(s(b,"status")))a.addField(others,"calories","王亦达本人摄入热量 · 千卡",s(b,"calories"),NUMBER);
  CheckBox agreed=null;if(self){agreed=new CheckBox(a);agreed.setText("已核对：提交后仅管理员可以修改或取消。");agreed.setTextColor(ui.text);others.addView(agreed);}final CheckBox confirmation=agreed;
  ui.fullButton(parent,self?"保存放纵餐记录":edit?"保存修改":"提交预约",true,()->{if(!a.need("name","restaurant","partySize","date","time"))return;if(self&&!confirmation.isChecked()){a.notifyError("请先核对并确认记录。");return;}try{JSONObject payload=collect(a,true);payload.put("action",self?"selfRecord":edit?"manageBooking":"book");if(edit)payload.put("id",s(a.selected(),"id"));a.save(payload);}catch(Exception e){a.notifyError(e.getMessage());}});
 }
 private static void addCompanion(MainActivity a,LinearLayout rows,String initial,Runnable changed){NativeUi ui=a.ui();LinearLayout row=ui.row();EditText name=ui.input(new LinearLayout(a),"",initial,TEXT);((ViewGroup)name.getParent()).removeView(name);name.setHint("一位同行人的姓名");LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,ui.dp(56),1);p.topMargin=ui.dp(12);row.addView(name,p);Button remove=ui.button("移除",false,()->{a.companions().remove(name);rows.removeView(row);changed.run();});row.addView(remove,new LinearLayout.LayoutParams(ui.dp(72),-2));rows.addView(row);a.companions().add(name);name.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int after){}public void onTextChanged(CharSequence s,int st,int before,int count){changed.run();}public void afterTextChanged(Editable e){}});}
 static JSONObject collect(MainActivity a,boolean validate){JSONObject result=new JSONObject();try{
  for(String key:a.fields().keySet())result.put(key,a.val(key));result.put("mealAt",a.val("date")+"T"+a.val("time"));result.put("mealType",choice(a,"mealType"));result.put("transportMode",choice(a,"transportMode"));StringJoiner names=new StringJoiner("、");for(EditText e:a.companions())if(!e.getText().toString().trim().isEmpty())names.add(e.getText().toString().trim());result.put("companions",names.toString());result.put("requestId",a.draft().optString("requestId",UUID.randomUUID().toString()));
  if(!a.draft().isNull("latitude")&&!a.draft().isNull("longitude")){result.put("latitude",a.draft().getDouble("latitude"));result.put("longitude",a.draft().getDouble("longitude"));result.put("coordinateSystem","gcj02");}
  if(validate){BookingLabels.parseCost(a.val("estimatedCost"));LocalDateTime meal=LocalDateTime.parse(result.getString("mealAt"));int size=Integer.parseInt(a.val("partySize"));if(size<1||size>30)throw new IllegalArgumentException("用餐人数须为1至30。");result.put("partySize",size);if(a.fields().containsKey("calories")){int n=Integer.parseInt(a.val("calories"));if(n<1||n>100000)throw new IllegalArgumentException("热量须为1至100000千卡。");result.put("calories",n);}if("self".equals(a.screen())&&meal.isAfter(LocalDateTime.now(CHINA)))throw new IllegalArgumentException("自主记录只能填写已经发生的用餐。");}
 }catch(Exception e){if(validate)throw new IllegalArgumentException(e instanceof NumberFormatException?"请输入有效的人数和热量。":e.getMessage());}return result;}
 static void quota(MainActivity a){NativeUi ui=a.ui();LinearLayout parent=a.body();ui.title(parent,"设置周额度","指定自然周优先于默认设置；0次表示暂停预约。");Spinner scope=spinner(a,parent,"scope","设置范围",new String[]{"默认每周额度","指定自然周"},new String[]{"default","week"},"default");EditText w=a.addField(parent,"week","周一日期",s(a.data(),"week"),TEXT);date(a,w,true,null);a.addField(parent,"limit","允许次数 · 0至100",String.valueOf(a.data().optInt("weekLimit",2)),NUMBER);ui.fullButton(parent,"保存额度",true,()->{if(!a.need("limit"))return;try{int n=Integer.parseInt(a.val("limit"));if(n<0||n>100)throw new Exception();a.save(ApiClient.object("action","manageQuota","week","default".equals(choice(a,"scope"))?"default":a.val("week"),"limit",n));}catch(Exception e){a.notifyError("请输入0至100的额度。");}});JSONArray limits=MainActivity.arr(a.data(),"weeklyLimits");ui.gap(parent,20);for(int i=0;i<limits.length();i++){JSONObject l=limits.optJSONObject(i);LinearLayout c=ui.card(parent);c.addView(ui.body(("default".equals(s(l,"week"))?"默认每周":s(l,"week"))+" · "+l.optInt("meal_limit")+" 次"));}}
 static void user(MainActivity a){NativeUi ui=a.ui();LinearLayout p=a.body();JSONObject u=a.selected();ui.title(p,"编辑用户",s(u,"username"));a.addField(p,"username","用户名",s(u,"username"),TEXT);a.addField(p,"nickname","昵称",s(u,"nickname"),TEXT);a.addField(p,"email","邮箱",s(u,"email"),TEXT|android.text.InputType.TYPE_TEXT_VARIATION_EMAIL_ADDRESS);CheckBox disabled=new CheckBox(a);disabled.setText("停用该普通用户");disabled.setTextColor(ui.text);disabled.setChecked(u.optInt("disabled")==1);if("user".equals(s(u,"role")))p.addView(disabled);ui.fullButton(p,"保存用户信息",true,()->{if(!a.need("username","email"))return;a.save(ApiClient.object("action","manageUser","id",s(u,"id"),"username",a.val("username"),"nickname",a.val("nickname"),"email",a.val("email"),"disabled",disabled.isChecked()));});}
